function dodance(%client) {
	if(!%client.dan) return;
	%armor = Player::getArmor(%client);
	if (%armor == "harmor" || %armor == "darmor") {
		%r = 43 + floor(getRandom() * 2);
		Player::setAnimation(%client, %r);
		if(%r == 43)
			schedule("dodance("@%client@");", 3.1);			
		else 
			schedule("dodance("@%client@");", 3.62);
	} else if (%armor == "marmor" || %armor == "barmor" || %armor == "larmor" || %armor == "iarmor") {
		Player::setAnimation(%client, 45);
		schedule("dodance("@%client@");", 3.25);
	} else if (%armor == "mfemale" || %armor == "bfemale" || %armor == "efemale" || %armor == "ifarmor") {
		Player::setAnimation(%client, 44);
		schedule("dodance("@%client@");", 2.5);
	} else if (%armor == "larmor" || %armor == "sarmor" || %armor == "spyarmor" || %armor == "dmarmor") {
		Player::setAnimation(%client, 44);
		schedule("dodance("@%client@");", 1.45);
	} else if (%armor == "lfemale" || %armor == "sfemale" || %armor == "spyfemale" || %armor == "dmfemale") {
		Player::setAnimation(%client, 43);
		schedule("dodance("@%client@");", 1.5);
	} else {
		Player::setAnimation(%client, 43 + floor(getRandom() * 3));
		schedule("dodance("@%client@");", 2.8);
	}
}

